sys_variable_value.value:
(function execute(inputs, outputs) {
    var scriptInc = new global.AAPGlobalAPI();
    gs.info('flow action catalogue item' + inputs.category.sys_id);
    var newSysID = scriptInc.createItem(inputs.name, inputs.category, inputs.catalogs); // Call the method with inputs
    outputs.result = newSysID; // Pass the new sys_id as output
})(inputs, outputs);

